<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { avanzarFase, crearFormulacion, listarFormulaciones, obtenerFormulacion, type FaseFormulacion, type FormulacionPresupuestal } from '../services/formulaciones'
const records=ref<FormulacionPresupuestal[]>([]),selected=ref<FormulacionPresupuestal|null>(null),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),modal=ref(false),year=ref(new Date().getFullYear()+1)
const phases:Array<{key:FaseFormulacion;number:number;title:string;text:string}>= [
  {key:'proyeccion',number:1,title:'Proyecciones',text:'Registro de ingresos, restricciones y cálculo del saldo operativo.'},
  {key:'distribucion',number:2,title:'Distribución',text:'Asignación porcentual del saldo a las unidades orgánicas principales.'},
  {key:'plan',number:3,title:'Planes de trabajo',text:'Programación de actividades y recursos necesarios por cada mes.'},
  {key:'consolidacion',number:4,title:'Consolidación PIA',text:'Consolidación de planes y generación del Presupuesto Institucional de Apertura.'},
]
const phaseIndex=computed(()=>selected.value?phases.findIndex(x=>x.key===selected.value?.fase):-1)
async function load(target=page.value){loading.value=true;error.value='';try{const r=await listarFormulaciones(target);records.value=r.data;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(e){error.value=message(e)}finally{loading.value=false}}
async function open(item:FormulacionPresupuestal){loading.value=true;error.value='';try{selected.value=await obtenerFormulacion(item.id)}catch(e){error.value=message(e)}finally{loading.value=false}}
async function create(){if(year.value<2000||year.value>2100){error.value='Ingrese un año válido.';return}saving.value=true;error.value='';try{const item=await crearFormulacion(year.value);modal.value=false;success.value=`Formulación ${item.anio} creada correctamente.`;await load(1);await open(item)}catch(e){error.value=message(e)}finally{saving.value=false}}
async function next(){if(!selected.value||!confirm('Se pasará a la siguiente fase y no se podrá volver. ¿Desea continuar?'))return;saving.value=true;error.value='';try{selected.value=await avanzarFase(selected.value.id);success.value='La formulación avanzó a la siguiente fase.';await load(page.value)}catch(e){error.value=message(e)}finally{saving.value=false}}
const money=(v=0)=>new Intl.NumberFormat('es-PE',{style:'currency',currency:'PEN'}).format(v),message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.'
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Presupuesto / Formulaciones</nav><header class="hero"><div class="mark">PIA</div><div><small>MIA · PRESUPUESTO</small><h1>Formulación presupuestal</h1><p>Proyecta, distribuye y consolida el presupuesto institucional.</p></div><button @click="modal=true">+ Crear formulación</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p>
<section v-if="selected" class="detail"><header><button class="back" @click="selected=null">← Volver</button><div><small>FORMULACIÓN PRESUPUESTAL</small><h2>Ejercicio {{selected.anio}}</h2></div><span>{{phases[phaseIndex]?.number}} de 4 · {{phases[phaseIndex]?.title}}</span></header><div class="totals"><article><small>INGRESOS PROYECTADOS</small><b>{{money(selected.total_ingresos)}}</b></article><article class="restricted"><small>RESTRICCIONES</small><b>{{money(selected.total_restricciones)}}</b></article><article class="balance"><small>SALDO OPERATIVO</small><b>{{money(selected.total_saldo)}}</b></article></div><div class="phases"><article v-for="(phase,index) in phases" :key="phase.key" :class="{active:index===phaseIndex,done:index<phaseIndex,locked:index>phaseIndex}"><div class="phase-number">{{index<phaseIndex?'✓':phase.number}}</div><div><small>FASE {{phase.number}}</small><h3>{{phase.title}}</h3><p>{{phase.text}}</p><template v-if="phase.key==='proyeccion'&&index<=phaseIndex"><div class="lines"><span>Ingresos <b>{{money(selected.total_ingresos)}}</b></span><span>Restricciones <b>{{money(selected.total_restricciones)}}</b></span><span>Operativo <b>{{money(selected.total_saldo)}}</b></span></div></template><template v-if="phase.key==='distribucion'&&index<=phaseIndex"><div class="lines"><span v-for="unit in selected.unidades_principales" :key="unit.id">{{unit.nombre}} ({{unit.porcentaje}}%) <b>{{money(unit.importe)}}</b></span><span v-if="!selected.unidades_principales?.length">Sin unidades principales asignadas.</span></div></template></div><footer v-if="index===phaseIndex"><button class="soft">{{phase.key==='proyeccion'?'Administrar proyección':phase.key==='distribucion'?'Distribuir presupuesto':phase.key==='plan'?'Ver planes':'Ver consolidación'}}</button><button v-if="index<3" :disabled="saving" @click="next">{{saving?'Procesando…':'Siguiente →'}}</button></footer></article></div></section>
<template v-else><section class="summary"><div><small>TOTAL FORMULACIONES</small><b>{{total}}</b></div><div><small>EN PROYECCIÓN</small><b>{{records.filter(x=>x.fase==='proyeccion').length}}</b></div><div><small>EN DISTRIBUCIÓN</small><b>{{records.filter(x=>x.fase==='distribucion').length}}</b></div><div><small>CONSOLIDADAS</small><b>{{records.filter(x=>x.fase==='consolidacion').length}}</b></div></section><div v-if="loading" class="empty">Cargando formulaciones…</div><div v-else-if="!records.length" class="empty">No hay formulaciones presupuestales registradas.</div><section v-else class="cards"><button v-for="item in records" :key="item.id" @click="open(item)"><div class="flask">⌁</div><div><small>FORMULACIÓN</small><h2>{{item.anio}}</h2><span>{{phases.find(x=>x.key===item.fase)?.title}}</span></div><i>→</i></button></section><footer v-if="lastPage>1" class="pager"><button :disabled="page===1" @click="load(page-1)">Anterior</button><span>Página {{page}} de {{lastPage}}</span><button :disabled="page===lastPage" @click="load(page+1)">Siguiente</button></footer></template>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="create"><header><div><small>NUEVO EJERCICIO</small><h2>Crear formulación</h2></div><button type="button" @click="modal=false">×</button></header><p>Registre el año para iniciar la fase de proyección presupuestal.</p><label>Año fiscal *<input v-model.number="year" type="number" min="2000" max="2100" required></label><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Creando…':'Crear formulación'}}</button></footer></form></div></div></template>
<style scoped>
.page{--accent:#d64f83;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:20px 23px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--accent);border-radius:12px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--accent);font-size:.65rem;font-weight:800}.hero small,.summary small,.detail small,.dialog small{color:var(--accent);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero button,.detail button,.dialog button,.pager button{padding:9px 12px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.52rem}.hero>button{margin-left:auto}.flash{padding:9px;border-radius:7px;color:#a64046;background:#fff0f0;font-size:.6rem}.flash.success{color:#287052;background:#edf9f3}.summary{margin-top:11px;display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.summary>div{padding:14px;display:grid;border-radius:9px;background:#fff}.summary b{font-size:1rem}.empty{margin-top:11px;padding:48px;text-align:center;border-radius:9px;background:#fff;font-size:.6rem}.cards{margin-top:11px;display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.cards button{padding:0;display:flex;align-items:stretch;border:0;border-radius:10px;overflow:hidden;text-align:left;color:inherit;background:#fff;box-shadow:0 2px 8px #34495e10;cursor:pointer}.flask{width:65px;display:grid;place-items:center;color:#fff;background:linear-gradient(145deg,var(--accent),#a83565);font-size:1.8rem}.cards button>div:nth-child(2){padding:16px}.cards small{color:#a1abb0;font-size:.45rem;font-weight:800}.cards h2{margin:2px 0;font-size:1.25rem}.cards span{font-size:.52rem;color:var(--accent)}.cards i{margin:auto 14px auto auto;color:var(--accent)}.pager{margin-top:12px;display:flex;align-items:center;justify-content:center;gap:10px;font-size:.52rem}.pager button:disabled{opacity:.45}.detail{margin-top:11px}.detail>header{padding:15px;display:flex;align-items:center;gap:12px;border-radius:9px;background:#fff}.detail h2{margin:2px 0;font-size:1rem}.detail>header>span{margin-left:auto;padding:6px 9px;border-radius:12px;color:var(--accent);background:#fbeaf1;font-size:.5rem}.back{color:#65747b!important;background:#edf1f3!important}.totals{margin-top:8px;display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.totals article{padding:13px;display:grid;border-top:3px solid #369d76;border-radius:8px;background:#fff}.totals b{font-size:.85rem}.totals .restricted{border-color:#df6b6b}.totals .balance{border-color:var(--accent)}.phases{margin-top:8px;display:grid;grid-template-columns:repeat(2,1fr);gap:9px}.phases article{padding:15px;display:grid;grid-template-columns:auto 1fr;gap:11px;border:1px solid #e1e7e9;border-radius:10px;background:#fff}.phases article.active{border:2px solid var(--accent);box-shadow:0 4px 15px #d64f8317}.phases article.locked{opacity:.5}.phase-number{width:31px;height:31px;display:grid;place-items:center;border-radius:50%;color:#fff;background:#a9b4b9;font-size:.6rem;font-weight:800}.active .phase-number{background:var(--accent)}.done .phase-number{background:#349b74}.phases h3{margin:2px 0;font-size:.72rem;text-transform:uppercase}.phases p{margin:4px 0;color:#79868c;font-size:.53rem;line-height:1.5}.lines{margin-top:8px;display:grid;border-top:1px solid #e7ebed}.lines span{padding:5px 0;display:flex;justify-content:space-between;font-size:.49rem}.phases article>footer{grid-column:1/-1;display:flex;justify-content:flex-end;gap:6px}.soft{color:#68777e!important;background:#edf1f3!important}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(440px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex}.dialog h2{margin:2px 0;font-size:1rem}.dialog>header button{margin-left:auto;color:#59666c;background:none;font-size:1.2rem}.dialog p{color:#77858b;font-size:.58rem}.dialog label{display:grid;gap:5px;font-size:.53rem}.dialog input{padding:9px;border:1px solid #d8e0e3;border-radius:6px}.dialog footer{margin-top:17px;display:flex;justify-content:flex-end;gap:6px}@media(max-width:850px){.hero{flex-wrap:wrap}.hero>button{margin-left:0}.summary,.cards,.totals,.phases{grid-template-columns:1fr}.detail>header{align-items:flex-start;flex-wrap:wrap}.detail>header>span{margin-left:0}}
</style>
